<script>
  import { onMount, onDestroy, tick, untrack } from 'svelte';
  import { widgetCatalog, widgetCategories, widgetPresentation } from './notification-widget-model.js';
  let { editor, state: widgetState, reminderWidgetProjection, calendarWidgetProjection, clock, foreground = true, execute, registerView } = $props();
  const projections = $derived({ ...calendarWidgetProjection, ...reminderWidgetProjection });
  let panel = $state(null), scroller = $state(null), error = $state(null), dragging = $state(false);
  let disposed = false, drag = null;
  let filterKey = null;
  $effect(() => {
    const currentFilter = JSON.stringify([editor.editorId, editor.category, editor.query]);
    if (scroller && currentFilter !== filterKey) {
      filterKey = currentFilter; scroller.scrollTop = 0; scroller.scrollLeft = 0;
    }
  });
  const lease = () => ({ editor, panel, scroller });
  const current = owner => !disposed && editor === owner.editor && panel === owner.panel && scroller === owner.scroller && panel?.dataset.widgetEditorId === editor.editorId;
  function mounted(node) { if (!foreground || !node?.isConnected || !panel?.contains(node) || panel.clientWidth <= 0 || panel.clientHeight <= 0) return false; for (let parent = node; parent; parent = parent.parentElement) { const style = parent.ownerDocument.defaultView.getComputedStyle(parent); if (parent.hidden || parent.inert || style.display === 'none' || ['hidden','collapse'].includes(style.visibility) || style.opacity === '0') return false; } return true; }
  const available = () => current(lease()) && mounted(panel);
  const nodes = () => available() ? [panel, ...panel.querySelectorAll('[data-widget-control]')].filter(node => mounted(node) && !node.disabled) : [];
  const control = id => nodes().find(node => node.dataset.widgetControl === id);
  const valid = (owner, guard) => current(owner) && available() && (typeof guard !== 'function' || guard() === true);
  const position = () => ({ top: scroller?.scrollTop ?? 0, left: scroller?.scrollLeft ?? 0 });
  function describe() { const all = nodes(); return { controlIds: all.map(node => node.dataset.widgetControl), focusedControl: all.find(node => node === node.ownerDocument.activeElement)?.dataset.widgetControl ?? null, scroll: position() }; }
  async function prepare(id, guard) { const owner = lease(), node = control(id); if (!node || !valid(owner, guard)) return false; await tick(); return valid(owner, guard) && control(id) === node; }
  async function focus(id, guard) { const owner = lease(), node = control(id); if (!node || !valid(owner, guard)) return false; await tick(); if (!valid(owner, guard) || node !== control(id)) return false; node.scrollIntoView({ block: 'nearest', inline: 'nearest' }); if (!valid(owner, guard) || node !== control(id)) return false; node.focus({ preventScroll: true }); return valid(owner, guard) && node.ownerDocument.activeElement === node; }
  async function scroll(offsets, guard) { const owner = lease(); if (!valid(owner, guard) || !mounted(scroller) || !Number.isFinite(offsets?.top) || !Number.isFinite(offsets?.left) || offsets.top < 0 || offsets.left < 0 || offsets.top > Number.MAX_SAFE_INTEGER || offsets.left > Number.MAX_SAFE_INTEGER) return null; await tick(); if (!valid(owner, guard) || !mounted(owner.scroller)) return null; owner.scroller.scrollTop = offsets.top; owner.scroller.scrollLeft = offsets.left; return valid(owner, guard) ? position() : null; }
  onMount(() => registerView({ available, describe, prepare, focus, scroll }));
  onDestroy(() => { disposed = true; drag = null; registerView(null); });
  $effect(() => { const owner = lease(), top = editor.scroll.top, left = editor.scroll.left; untrack(() => { if (valid(owner) && scroller) { scroller.scrollTop = top; scroller.scrollLeft = left; } }); });
  $effect(() => { if (!foreground) { drag = null; dragging = false; } });
  async function request(command, payload = {}, node = panel) { const owner = lease(); if (!valid(owner) || !mounted(node)) return; try { const result = await execute(`widgets.${command}`, { centerId: owner.editor.centerId, editorId: owner.editor.editorId }, payload); if (current(owner) && mounted(node)) error = result.status === 'rejected' ? result.error.message : null; } catch (cause) { if (current(owner)) error = cause?.message ?? 'Widget request failed.'; } }
  function configuration(kind) { const sources = widgetState.sources; switch (kind) { case 'calendar': return { calendarIds: calendarWidgetProjection.calendars.map(row => row.id) }; case 'weather': return { locationId: sources.weather[0]?.id ?? null, unit: 'celsius' }; case 'reminders': return { listId: reminderWidgetProjection.reminderLists[0]?.id ?? null }; case 'stock-symbol': return { symbolId: sources.stocks[0]?.id ?? null }; case 'stock-watchlist': return { symbolIds: sources.stocks.map(row => row.id) }; case 'clock-city': return { cityId: sources.clockCities[0]?.id ?? null }; default: return { cityIds: sources.clockCities.slice(0,4).map(row => row.id) }; } }
  const filtered = $derived(widgetCatalog.filter(item => (editor.category === 'all' || item.category === editor.category) && `${item.label} ${item.category} ${item.description}`.toLowerCase().includes(editor.query.toLowerCase())));
  function startDrag(event, kind, size) { if (event.button !== 0 || !available()) return; const center = panel.ownerDocument.querySelector(`[data-notification-center-id="${editor.centerId}"]`); if (!center?.isConnected) return; drag = { owner: lease(), node: event.currentTarget, kind, size, center, pointerId: event.pointerId, x: event.clientX, y: event.clientY }; event.currentTarget.setPointerCapture(event.pointerId); }
  function moveDrag(event) { if (drag?.pointerId === event.pointerId && Math.hypot(event.clientX - drag.x, event.clientY - drag.y) > 8) dragging = true; }
  function endDrag(event) { const original = drag, moved = dragging; drag = null; dragging = false; if (!original || !moved || original.pointerId !== event.pointerId || !valid(original.owner) || !mounted(original.node) || !original.center.isConnected || original.center.dataset.notificationCenterId !== editor.centerId) return; const bounds = original.center.getBoundingClientRect(); if (event.clientX >= bounds.left && event.clientX <= bounds.right && event.clientY >= bounds.top && event.clientY <= bounds.bottom) void request('add', { kind: original.kind, size: original.size }, original.node); }
  function focusChanged() { if (available()) editor.focusedControl = describe().focusedControl; }
  function scrollChanged() { const offsets = position(); if (available() && (offsets.top !== editor.scroll.top || offsets.left !== editor.scroll.left)) void request('scroll', offsets); }
</script>
<svelte:window onpointerup={endDrag} onpointercancel={() => { drag = null; dragging = false; }} />
<div class="gallery" role="dialog" aria-label="Widget Gallery" aria-modal="false" class:dragging data-widget-editor-id={editor.editorId} data-widget-control="editor" tabindex="-1" bind:this={panel} onfocusin={focusChanged} onkeydown={event => { if (event.key === 'Escape' && !event.isComposing) { event.preventDefault(); event.stopPropagation(); void request('editor.close'); } }}>
  <header><h2>Edit Widgets</h2><button class="done" data-widget-control="done" onclick={() => request('editor.close')}>Done</button></header>
  <div class="layout"><aside><input class="search" type="search" aria-label="Search Widgets" placeholder="Search Widgets" maxlength="256" value={editor.query} data-widget-control="search" oninput={event => request('editor.search', { query: event.currentTarget.value }, event.currentTarget)} />
    <select class="category-picker" aria-label="Widget category" data-widget-control="categories" value={editor.category}
      onchange={event => request('editor.category', { category: event.currentTarget.value }, event.currentTarget)}>
      {#each widgetCategories as category}<option value={category}>{category === 'all' ? 'All Widgets' : category}</option>{/each}
    </select>
    <nav aria-label="Widget categories">{#each widgetCategories as category}<button data-widget-control={`category:${category}`} aria-pressed={editor.category === category} onclick={() => request('editor.category', { category })}>{category === 'all' ? 'All Widgets' : category}</button>{/each}</nav>
  </aside><main bind:this={scroller} onscroll={scrollChanged}>
    <p class="intro">Choose a size, then add to Notification Center. You can also drag a preview there.</p>
    {#if error}<p role="alert" class="error">{error}</p>{/if}
    {#each filtered as item (item.kind)}<section><h3>{item.label}</h3><p class="description">{item.description}</p><div class="previews">{#each item.sizes as size}{@const view = widgetPresentation(widgetState, { id: 'preview', kind: item.kind, size, configuration: configuration(item.kind) }, clock, projections)}
      <div class="choice"><div class="preview {size} {item.kind}" role="img" aria-label={`${item.label} ${size} preview; drag to Notification Center`} onpointerdown={event => startDrag(event, item.kind, size)} onpointermove={moveDrag} onpointerup={endDrag}><strong>{view.title}</strong>
        {#if view.date}<div class="preview-date">{view.date.weekday}<b>{view.date.day}</b><small>{view.date.monthLabel}</small></div>{/if}
        {#if view.events}<div class="rows">{#each view.events.slice(0,size === 'large' ? 4 : 2) as event}<span><small>{event.time}</small> {event.title}</span>{:else}<span>No upcoming events</span>{/each}</div>{/if}
        {#if view.weather}<b class="degrees">{view.weather.temperatureText}</b><span>{view.weather.name}</span><small>{view.weather.conditionText} · H:{view.weather.highText} L:{view.weather.lowText}</small>{#if size !== 'small'}<div class="hours">{#each view.weather.hourly.slice(0,4) as hour}<span>{hour.time}<br />{hour.temperatureText}</span>{/each}</div>{/if}{:else if item.kind === 'weather'}<span>No location selected</span>{/if}
        {#if view.reminders}<div class="rows">{#each view.reminders.slice(0,size === 'large' ? 5 : 3) as reminder}<span>○ {reminder.title}</span>{:else}<span>No reminders</span>{/each}</div>{/if}
        {#if view.stocks}<small>Fictional market</small>{#each view.stocks.slice(0,size === 'large' ? 4 : 2) as stock}<span>{stock.symbol} · {stock.priceText}</span><svg viewBox="0 0 100 40" preserveAspectRatio="none" aria-label="Price history"><polyline points={stock.points} fill="none" stroke="currentColor" stroke-width="2" /></svg>{:else}<span>No symbols selected</span>{/each}{/if}
        {#if view.clocks}<div class="clock-previews">{#each view.clocks as city}<div><svg viewBox="0 0 100 100" aria-label={city.time}><circle cx="50" cy="50" r="46" fill="var(--appearance-surface,#fff)" stroke="#999"/><line x1="50" y1="50" x2="50" y2="27" stroke="currentColor" stroke-width="4" transform={`rotate(${city.hour * 30 + city.minute / 2} 50 50)`}/><line x1="50" y1="50" x2="50" y2="12" stroke="currentColor" stroke-width="2" transform={`rotate(${city.minute * 6} 50 50)`}/></svg><small>{city.name}</small></div>{:else}<span>No cities selected</span>{/each}</div>{/if}
      </div><span class="size-label">{size}</span><button class="add" data-widget-control={`add:${item.kind}:${size}`} onclick={() => request('add', { kind: item.kind, size })}>Add to Notification Center</button></div>
    {/each}</div></section>{:else}<p class="empty">No widgets match “{editor.query}”. Try another search or category.</p>{/each}
  </main></div>
</div>
<style>
.gallery{height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;color:var(--appearance-ink,#242427);background:color-mix(in srgb,var(--appearance-surface,#f4f4f6) 94%,transparent);font:12px -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;backdrop-filter:blur(30px);overflow:hidden}.gallery>header{display:flex;align-items:center;justify-content:space-between;padding:10px 16px;border-bottom:1px solid var(--appearance-soft-border,#8883);flex-shrink:0}h2{font-size:14px;margin:0}button,input{font:inherit;color:inherit}.done,.add{border:0;border-radius:7px;background:var(--appearance-focus,#0878ef);color:white;padding:5px 12px}button:focus-visible,input:focus-visible,.gallery:focus-visible{outline:2px solid var(--appearance-focus,#0878ef);outline-offset:2px}.layout{display:flex;min-height:0;flex:1}aside{width:154px;flex-shrink:0;padding:12px;border-right:1px solid var(--appearance-soft-border,#8883);overflow:auto;scrollbar-width:thin}.search{box-sizing:border-box;width:100%;background:#8881;border:1px solid #8883;border-radius:7px;padding:6px;font-size:11px}nav{display:flex;flex-direction:column;gap:3px;margin-top:12px}nav button{border:0;background:transparent;text-align:left;padding:7px 9px;border-radius:7px}nav button[aria-pressed=true]{background:var(--appearance-focus,#0878ef);color:#fff}main{min-width:0;flex:1;overflow:auto;padding:12px 20px;scrollbar-width:thin}.intro{font-size:11px;opacity:.65;margin:0 0 15px}h3{font-size:14px;margin:0 0 4px}.description{font-size:11px;opacity:.65;margin:0 0 12px}section{margin-bottom:26px}.previews{display:flex;flex-wrap:wrap;gap:18px;align-items:flex-start}.choice{display:flex;flex-direction:column;gap:7px;align-items:center;max-width:100%;min-width:0}.preview{box-sizing:border-box;display:flex;flex-direction:column;gap:4px;width:142px;height:142px;padding:13px;border-radius:21px;overflow:hidden;background:var(--appearance-surface,#fff);box-shadow:0 4px 15px #0002;border:1px solid var(--appearance-light-edge,#fff8);touch-action:none;user-select:none}.preview.medium{width:280px}.preview.large{width:280px;height:280px}.preview>strong{font-size:10px}.preview span{font-size:11px}.preview small{font-size:9px;opacity:.7}.preview-date{display:flex;flex-direction:column;color:#e85244;font-size:11px}.preview-date b{color:var(--appearance-ink,#222);font-size:40px;font-weight:400;line-height:1.1}.rows{display:flex;flex-direction:column;gap:6px;overflow:hidden}.rows span{border-bottom:1px solid #8882;padding:3px 0}.weather{background:linear-gradient(135deg,#286eaf,#75aad2);color:#fff}.degrees{font-size:35px;font-weight:300}.hours{display:flex;justify-content:space-between;margin-top:6px}.preview>svg{height:25px;width:100%;color:#37a76b;flex-shrink:0}.clock-previews{display:flex;gap:8px}.clock-previews>div{flex:1;min-width:0;text-align:center}.clock-previews svg{width:100%;max-width:100px}.size-label{text-transform:capitalize;font-size:10px;opacity:.65}.add{font-size:10px;max-width:100%;white-space:normal}.empty,.error{font-size:12px;line-height:1.5}.error{color:#db564d}.dragging .preview{cursor:grabbing}.dragging .intro{color:var(--appearance-focus,#0878ef);opacity:1}@media(max-width:480px){aside{width:95px;padding:7px}main{padding:8px}nav button{padding:6px;font-size:11px}.gallery>header{padding:6px 10px}.preview.medium,.preview.large{width:190px}.previews{gap:12px}.intro{font-size:10px}.search{font-size:10px;padding:5px}.preview{width:135px;height:135px}}
  .category-picker { display:none; box-sizing:border-box; width:100%; margin-top:8px; padding:4px; color:inherit; background:var(--appearance-surface,#fff); border:1px solid var(--appearance-soft-border,#8883); border-radius:6px; font:inherit; font-size:10px; }
  @media(max-height:480px) { aside { overflow:hidden; } nav { display:none; } .category-picker { display:block; } }
</style>
